mapper.select:
SELECT * FROM ( SELECT R.RESV_ID AS resvId, R.ROOM_ID AS roomId, R.CHECKIN_DATE AS checkinDate, R.CHECKOUT_DATE AS checkoutDate, R.TOTAL_AMOUNT AS resvAmount, NVL(B.FEE_RATE, 10) AS feeRate, 'STAY' AS itemType FROM TB_RESERVATION R JOIN TB_STAY S ON R.RESV_TYPE = 'STAY' AND S.STAY_ID = TO_NUMBER(R.TARGET_ID) JOIN TB_BUSINESS B ON B.BIZ_NO = S.BIZ_NO WHERE S.BIZ_NO = #{bizNo} AND R.RESV_TYPE = 'STAY' AND R.STATUS_CD = 'DONE' AND ( (R.CHECKOUT_DATE >= TRUNC(#{periodStart}) AND R.CHECKOUT_DATE < TRUNC(#{periodEnd}) + 1) OR ( /* 2026/07/31 장우철 — R3-3: 환불거절 후 미정산 이월 */ /* 2026/08/06 장우철 — REJECTED(+레거시 DONE) */ R.CHECKOUT_DATE < TRUNC(#{periodStart}) AND EXISTS ( SELECT 1 FROM TB_INQUIRY I WHERE I.REF_TYPE = 'RESV' AND I.REF_ID = R.RESV_ID AND I.INQUIRY_TYPE = 'RESERVE' AND I.TITLE LIKE '숙소 환불신청%' AND I.STATUS_CD IN ('REJECTED', 'DONE') ) ) ) AND NOT EXISTS ( SELECT 1 FROM TB_SETTLEMENT_ITEM SI WHERE SI.RESV_ID = R.RESV_ID AND SI.STATUS_CD IN ('INCLUDED', 'HOLD', 'EXCLUDED', 'REFUNDED') ) AND NOT EXISTS ( /* 2026/07/31 장우철 — R3: 환불 심사중(WAIT)은 정산 보류 */ SELECT 1 FROM TB_INQUIRY I WHERE I.REF_TYPE = 'RESV' AND I.REF_ID = R.RESV_ID AND I.INQUIRY_TYPE = 'RESERVE' AND I.STATUS_CD = 'WAIT' ) AND NOT EXISTS ( /* 2026/08/06 장우철 — 환불승인(보상숙박)은 정산 제외 */ SELECT 1 FROM TB_INQUIRY I WHERE I.REF_TYPE = 'RESV' AND I.REF_ID = R.RESV_ID AND I.INQUIRY_TYPE = 'RESERVE' AND I.TITLE LIKE '숙소 환불신청%' AND I.STATUS_CD = 'APPROVED' )
AND R.ROOM_ID = #{roomId}
UNION ALL
SELECT R.RESV_ID AS resvId, R.ROOM_ID AS roomId, R.CHECKIN_DATE AS checkinDate, R.CHECKOUT_DATE AS checkoutDate, R.CANCEL_FEE_AMT AS resvAmount, NVL(B.FEE_RATE, 10) AS feeRate, 'CANCEL_FEE' AS itemType FROM TB_RESERVATION R JOIN TB_STAY S ON R.RESV_TYPE = 'STAY' AND S.STAY_ID = TO_NUMBER(R.TARGET_ID) JOIN TB_BUSINESS B ON B.BIZ_NO = S.BIZ_NO WHERE S.BIZ_NO = #{bizNo} AND R.RESV_TYPE = 'STAY' AND R.STATUS_CD = 'CANCEL' AND NVL(R.CANCEL_FEE_AMT, 0) > 0 AND R.CANCEL_AT >= TRUNC(#{periodStart}) AND R.CANCEL_AT < TRUNC(#{periodEnd}) + 1 AND NOT EXISTS ( SELECT 1 FROM TB_SETTLEMENT_ITEM SI WHERE SI.RESV_ID = R.RESV_ID AND SI.STATUS_CD IN ('INCLUDED', 'HOLD', 'EXCLUDED', 'REFUNDED') )
AND R.ROOM_ID = #{roomId}
) T ORDER BY T.checkoutDate ASC NULLS LAST, T.resvId ASC

SELECT FEE_RATE
  FROM TB_BUSINESS
 WHERE BIZ_NO = #{bizNo}

SELECT COUNT(*)
  FROM TB_STAY_ROOM SR
  JOIN TB_STAY S ON S.STAY_ID = SR.STAY_ID
 WHERE S.BIZ_NO = #{bizNo}
   AND SR.ROOM_ID = #{roomId}

SELECT COUNT(*)
  FROM TB_SETTLEMENT_REQUEST
 WHERE BIZ_NO = #{bizNo}
   AND STATUS_CD IN ('REQUESTED', 'APPROVED')
   AND REQUEST_SCOPE = #{requestScope}
   AND TRUNC(TARGET_START) = TRUNC(#{targetStart})
   AND TRUNC(TARGET_END)   = TRUNC(#{targetEnd})


   AND ROOM_ID = #{roomId}


   AND ROOM_ID IS NULL

SELECT BIZ_NAME
  FROM TB_BUSINESS
 WHERE BIZ_NO = #{bizNo}

mapper.update:
UPDATE TB_SETTLEMENT_ITEM
   SET STATUS_CD   = 'REFUNDED',
       HOLD_REASON = #{holdReason, jdbcType=VARCHAR}
 WHERE RESV_ID = #{resvId}
   AND STATUS_CD IN ('INCLUDED', 'HOLD')

mapper.select:
SELECT COUNT(*)
  FROM TB_SETTLEMENT
 WHERE BIZ_NO = #{bizNo}
   AND BIZ_TYPE = 'STAY'
   AND NVL(REQUEST_TYPE, 'REGULAR') = 'REGULAR'
   AND SETTLE_MONTH = #{settleMonth}
